import ast,itertools,types,math
from pathlib import Path
# Minimal standard-library array semantics for extracted combinatorial helpers.
# This does not emulate PyTorch autograd, autocast, attention, or full forward.
def indices(shape): return itertools.product(*(range(n) for n in shape))
class A:
 def __init__(self,shape,fn): self.shape=tuple(shape); self.v={i:fn(i) for i in indices(self.shape)}; self.device='cpu'
 @classmethod
 def rows(cls,rows): return cls((len(rows),len(rows[0])),lambda i:rows[i[0]][i[1]])
 def binary(self,other,fn):
  if not isinstance(other,A): return A(self.shape,lambda i:fn(self.v[i],other))
  n=max(len(self.shape),len(other.shape)); sa=(1,)*(n-len(self.shape))+self.shape; sb=(1,)*(n-len(other.shape))+other.shape
  assert all(a==b or a==1 or b==1 for a,b in zip(sa,sb)),(sa,sb)
  shape=tuple(b if a==1 else a for a,b in zip(sa,sb))
  def val(i,x,s): return x.v[tuple(0 if d==1 else j for j,d in zip(i,s))[n-len(x.shape):]]
  return A(shape,lambda i:fn(val(i,self,sa),val(i,other,sb)))
 def __and__(self,o): return self.binary(o,lambda a,b:bool(a and b))
 def __invert__(self): return A(self.shape,lambda i:not self.v[i])
 def __eq__(self,o): return self.binary(o,lambda a,b:a==b)
 def __ne__(self,o): return self.binary(o,lambda a,b:a"'!=b)
 def __gt__(self,o): return self.binary(o,lambda a,b:a>b)
 def __ge__(self,o): return self.binary(o,lambda a,b:a>=b)
 def __add__(self,o): return self.binary(o,lambda a,b:a+b)
 def __mul__(self,o): return self.binary(o,lambda a,b:a*b)
 def __truediv__(self,o): return self.binary(o,lambda a,b:a/b)
 def __rsub__(self,o): return A(self.shape,lambda i:o-self.v[i])
 def float(self): return A(self.shape,lambda i:float(self.v[i]))
 def __getitem__(self,key):
  if not isinstance(key,tuple): key=(key,)
  key=key+(slice(None),)*(len(self.shape)-sum(k is not None for k in key))
  specs=[]; out=[]; old=0
  for k in key:
   if k is None: specs.append(('"'new',None)); out.append(1)
   elif isinstance(k,int): specs.append(('int',k%self.shape[old])); old+=1
   else:
    select=list(range(self.shape[old]))[k]; specs.append(('slice',select)); out.append(len(select)); old+=1
  def get(i):
   orig=[]; n=0
   for kind,arg in specs:
    if kind=='new': n+=1
    elif kind=='int': orig.append(arg)
    else: orig.append(arg[i[n]]); n+=1
   return self.v[tuple(orig)]
  return A(out,get)
 def sum(self,dim=-1):
  dim%=len(self.shape); out=self.shape[:dim]+self.shape[dim+1:]
  return A(out,lambda i:sum(self.v[i[:dim]+(j,)+i[dim:]] for j in range(self.shape[dim])))
 def clamp_min(self,n): return A(self.shape,lambda i:max(n,self.v[i]))
def stack(arrays,dim):
 shape=list(arrays[0].shape); shape.insert(dim,len(arrays))
 return A(shape,lambda i:arrays[i[dim]].v[i[:dim]+i[dim+1:]])
torch=types.SimpleNamespace(arange=lambda n,device=None:A((n,),lambda i:i[0]),stack=stack)
tree=ast.parse(Path('candidate.py').read_text()); model=next(x for x in tree.body if isinstance(x,ast.ClassDef) and x.name=='Model')
methods=[x for x in model.body if isinstance(x,ast.FunctionDef) and x.name in ('_feedback_membership','_interpolate_rates')]
ns={'torch':torch}; exec(compile(ast.Module(body=methods,type_ignores=[]),'actual_helpers','exec'),ns)
obj=types.SimpleNamespace(recent_window=16,match_padding={'cate_id':0,'brand':0},shrinkage_strength=4.,rate_interpolation='count')
cases=0
for length in (0,1,4,17,100):
 valid=A((3,length),lambda i:(i[0]==0 or (i[0]==1 and i[1]%3"'!=0)))
 item={name:A((3,length+1),lambda i:2 if i[1]==length else (0 if i[1]%5==0 else (2 if i[1]%3 else 3))) for name in ('"'cate_id','brand')}
 members=ns['_feedback_membership'](obj,item,valid)
 assert members.shape==(3,8,length)
 for b in range(3):
  for j in range(length):
   assert sum(members.v[b,k,j] for k in range(8))==int(valid.v[b,j])
   cat=item['cate_id'].v[b,j]==2; brand=item['brand'].v[b,j]==2
   expected=2*cat+brand+4*(j>=max(length-16,0))
   if valid.v[b,j]: assert members.v[b,expected,j]==1
 changed={name:A((3,length+1),lambda i,src=src:src.v[i] if i[1]==length or valid.v[i[0],i[1]] else 2) for name,src in item.items()}
 assert ns['_feedback_membership'](obj,changed,valid).v==members.v
 counts=members.sum(-1)
 feedback=A((3,4,length),lambda i:float(valid.v[i[0],i[2]] and (i[1]+i[2])%3==0))
 fractions=A((3,8,4),lambda i:sum(members.v[i[0],i[1],j]*feedback.v[i[0],i[2],j] for j in range(length))/max(1,counts.v[i[:2]]))
 for mode in ('count','fixed'):
  obj.rate_interpolation=mode
  rate=ns['_interpolate_rates'](obj,fractions,counts,feedback,valid)
  for i,v in rate.v.items():
   b,k,t=i; n=counts.v[b,k]; w=n/(n+4) if mode=='count' else .5
   bg=sum(feedback.v[b,t,j] for j in range(length))/max(1,sum(valid.v[b,j] for j in range(length)))
   assert abs(v-(w*fractions.v[i]+(1-w)*bg))<1e-12
   assert 0<=v<=1
   if n==4: assert abs(v-(.5*fractions.v[i]+.5*bg))<1e-12
 cases+=1
# Nonzero padding cannot create matches.
obj.match_padding={'cate_id':7,'brand':7}
v=A((1,1),lambda i:True); it={n:A((1,2),lambda i:7) for n in ('cate_id','brand')}
m=ns['_feedback_membership'](obj,it,v); assert m.v[0,4,0]==1
print('PASS: extracted actual membership/rate helpers; 5 lengths x 3 history patterns, both interpolation modes, masked-ID perturbations, disjoint complete routing, zero and nonzero padding, empty histories, convex bounds and n=4 coincidence.')
print('LIMIT: standard-library combinatorial checks only; no PyTorch forward/backward/BF16/numerical scoring performed.')
PY"

